/// <summary>
/// extension of SalesQuotationHeaderTmp
/// </summary>
[ExtensionOf(tableStr(SalesQuotationHeaderTmp))]
final class AVASalesQuotationHeaderTmp_Extension
{
}

Method.Source:
/// <summary>
/// insert record
/// </summary>
public void insert()
{
    next insert();

    //copy of the SalesQuotationHeaderTmp from UsingExistingReportData()
    if(this.AVAOrigSalesQuotationHeaderTmp && this.AVAOrigSalesQuotationHeaderTmp != this.RecId)
    {
        //copy the markup
        AvaReportingMarkupTransTmp::copyMarkupTrans(this.TableId, this.AVAOrigSalesQuotationHeaderTmp, this.RecId);
        //reset the isCopy flag
        AvaReportingMarkupTransTmp::resetIsCopy(this.TableId, this.RecId, this.RecId);
    }
    else
    {
        //fill the markuptrans records
        CustQuotationJour custQuotationJour = CustQuotationJour::findRecId(this.CustQuotationJour);
        if(custQuotationJour)
        {
            boolean proforma = custQuotationJour.isProforma();
            SalesQuotationTable salesQuotationTable = custQuotationJour.salesQuotationTable();

            if(proforma)
            {
                AvaReportingMarkupTransTmp::setMarkupTrans(this, salesQuotationTable, custQuotationJour.LanguageId, proforma, custQuotationJour.Qty, custQuotationJour.SalesBalance, 0.0, salesQuotationTable.InclTax);
            }
            else
            {
                AvaReportingMarkupTransTmp::setMarkupTrans(this, custQuotationJour, custQuotationJour.LanguageId);
            }
        }
    }

    this.AVAOrigSalesQuotationHeaderTmp = this.RecId;
    this.doUpdate();

}
